import { spawn } from "node:child_process";
import { mkdirSync } from "node:fs";
import { homedir, userInfo } from "node:os";
import { join } from "node:path";
import { createInterface } from "node:readline";

export const CLAUDE_BIN = process.env.CLAUDE_BIN ?? join(homedir(), ".local/bin/claude");

// Sessions are keyed by cwd, so a dedicated directory keeps them out of every project's history.
export const WORKDIR = join(homedir(), ".ask-haiku");

// Raycast launches with a bare environment. The CLI looks up its keychain login by $USER, so without it
// the call fails with "Not logged in" even though the login exists.
export function childEnv(): NodeJS.ProcessEnv {
  return { ...process.env, HOME: homedir(), USER: process.env.USER ?? userInfo().username };
}

const TIMEOUT_MS = 180_000;

const SYSTEM_PROMPT =
  "Search the web when the question needs current information. " +
  "For facts that change, such as versions, prices or dates, open the authoritative page with WebFetch instead of trusting search snippets. " +
  "Answer concisely in markdown and cite sources as markdown links. " +
  "Keep answers under 80 words unless the user asks for detail.";

type ModelUsage = { webSearchRequests?: number };

export type ClaudeResult = {
  result: string;
  raw: {
    is_error?: boolean;
    duration_ms?: number;
    total_cost_usd?: number;
    modelUsage: Record<string, ModelUsage>;
  };
};

/**
 * Runs one turn. `onText` receives the answer text so far as it streams in; the resolved `result` is the
 * authoritative final text.
 */
export function askClaude(
  prompt: string,
  sessionId: string,
  first: boolean,
  onText?: (textSoFar: string) => void,
): Promise<ClaudeResult> {
  mkdirSync(WORKDIR, { recursive: true });

  const args = [
    "-p",
    "--model", "haiku",
    "--safe-mode",
    // --safe-mode keeps the user's output style; override it so answers aren't padded with extras.
    "--settings", '{"outputStyle":"default"}',
    "--effort", "low",
    // WebFetch lets the model read the authoritative page; search snippets alone gave stale version numbers.
    "--tools", "WebSearch,WebFetch",
    "--allowedTools", "WebSearch", "WebFetch",
    first ? "--session-id" : "--resume", sessionId,
    "--output-format", "stream-json",
    "--verbose",
    "--include-partial-messages",
    "--append-system-prompt", SYSTEM_PROMPT,
  ];

  return new Promise((resolve, reject) => {
    // The prompt goes over stdin so a leading "-" or a long question can't be parsed as a flag.
    const child = spawn(CLAUDE_BIN, args, { cwd: WORKDIR, env: childEnv() });
    const timer = setTimeout(() => child.kill(), TIMEOUT_MS);

    let stderr = "";
    let text = "";
    let final: ClaudeResult | undefined;

    child.stderr.on("data", (chunk) => (stderr += chunk));

    createInterface({ input: child.stdout }).on("line", (line) => {
      let msg;
      try {
        msg = JSON.parse(line);
      } catch {
        return;
      }
      if (msg.type === "stream_event") {
        const ev = msg.event;
        // Each assistant message restarts the text, so a preamble before a tool call is dropped.
        if (ev.type === "message_start") text = "";
        else if (ev.type === "content_block_delta" && ev.delta?.type === "text_delta") {
          text += ev.delta.text;
          onText?.(text);
        }
      } else if (msg.type === "result" && typeof msg.result === "string") {
        final = { result: msg.result, raw: msg };
      }
    });

    child.on("error", (e) => {
      clearTimeout(timer);
      reject(e);
    });
    child.on("close", (code) => {
      clearTimeout(timer);
      if (final && !final.raw.is_error) resolve(final);
      else reject(new Error(final?.result || stderr.trim() || `claude exited with code ${code}`));
    });

    child.stdin.end(prompt);
  });
}
