import { Action, ActionPanel, LaunchProps, List, Toast, showToast } from "@raycast/api";
import { useEffect, useRef, useState } from "react";
import { Asker } from "./lib/fast";

// `partial` is the streamed text so far; `a` is the final answer and takes over when the turn completes.
// `status` names the phase of the pipeline while nothing has streamed yet.
type Turn = { q: string; a?: string; partial?: string; status?: string; error?: string };

export default function Command(props: LaunchProps<{ arguments: Arguments.Ask }>) {
  const [text, setText] = useState("");
  const [turns, setTurns] = useState<Turn[]>([]);
  const [loading, setLoading] = useState(false);
  const asker = useRef<Asker | undefined>(undefined);

  // Spawning here, not on the first question, lets the claude process start while the user is typing.
  useEffect(() => {
    asker.current = new Asker();
    return () => asker.current?.close();
  }, []);

  async function send(question: string) {
    const q = question.trim();
    if (!q || loading || !asker.current) return;
    const patch = (p: Partial<Turn>) =>
      setTurns((all) => all.map((t, i) => (i === all.length - 1 ? { ...t, ...p } : t)));

    setTurns((all) => [...all, { q }]);
    setText("");
    setLoading(true);
    let lastPaint = 0;
    const onText = (partial: string) => {
      const now = Date.now();
      if (now - lastPaint < 100) return;
      lastPaint = now;
      patch({ partial });
    };

    try {
      const { result } = await asker.current.ask(q, { onText, onStatus: (status) => patch({ status }) });
      patch({ a: result });
    } catch (e) {
      const error = (e as Error).message;
      patch({ error });
      showToast({ style: Toast.Style.Failure, title: "Claude failed", message: error.slice(0, 120) });
    } finally {
      setLoading(false);
    }
  }

  const initial = useRef<string | undefined>(props.arguments.query);
  useEffect(() => {
    if (initial.current) {
      send(initial.current);
      initial.current = undefined;
    }
  }, []);

  // Newest first, so the latest answer is what's selected after each send.
  const newestFirst = [...turns].reverse();

  return (
    <List
      isLoading={loading}
      isShowingDetail={turns.length > 0 || text.length > 0}
      filtering={false}
      searchText={text}
      onSearchTextChange={setText}
      searchBarPlaceholder="Ask Haiku…"
    >
      {text.trim() && (
        <List.Item
          title={`Ask: ${text.trim()}`}
          detail={<List.Item.Detail markdown="Press ↵ to search the web and answer." />}
          actions={
            <ActionPanel>
              <Action title="Ask" onAction={() => send(text)} />
            </ActionPanel>
          }
        />
      )}
      {newestFirst.map((t, i) => (
        <List.Item
          key={turns.length - i}
          title={t.q}
          detail={<List.Item.Detail markdown={render(t)} />}
          actions={
            <ActionPanel>
              {t.a && <Action.CopyToClipboard title="Copy Answer" content={t.a} />}
            </ActionPanel>
          }
        />
      ))}
    </List>
  );
}

function render(t: Turn): string {
  if (t.error) return `**Error**\n\n\`\`\`\n${t.error}\n\`\`\``;
  return t.a ?? t.partial ?? `_${t.status ?? "Searching"}…_`;
}
