import { spawn, type ChildProcessWithoutNullStreams } from "node:child_process";
import { randomUUID } from "node:crypto";
import { mkdirSync } from "node:fs";
import { createInterface } from "node:readline";
import { askClaude, childEnv, CLAUDE_BIN, WORKDIR, type ClaudeResult } from "./claude";
import { bingSearch, excerpt, fetchLines, type Hit } from "./web";

/*
 * Fast path. The agentic path (claude with WebSearch/WebFetch) spends about 60% of its time inside sequential
 * tool calls. Here one long-lived tool-less `claude` process plans the queries, this module searches and
 * fetches in parallel, and the same process writes the answer. If the sources aren't enough it falls back to
 * the agentic path.
 */

const FAST_SYSTEM = "You are a fast, accurate research assistant. Be concise.";

const FAST_ARGS = [
  "-p",
  "--model", "haiku",
  "--safe-mode",
  "--settings", '{"outputStyle":"default"}',
  "--effort", "low",
  "--tools", "",
  "--no-session-persistence",
  "--input-format", "stream-json",
  "--output-format", "stream-json",
  "--verbose",
  "--include-partial-messages",
  "--system-prompt", FAST_SYSTEM,
];

const BLOCKED_HOSTS = /(^|\.)(youtube\.com|youtu\.be|facebook\.com|instagram\.com|tiktok\.com|x\.com|twitter\.com|reddit\.com|linkedin\.com)$/;
const STOPWORDS = new Set("a an and are as at be by for from how in is it of on or the to what when where which who why with".split(" "));

type Pending = {
  resolve: (r: ClaudeResult) => void;
  reject: (e: Error) => void;
  text: string;
  onText?: (textSoFar: string) => void;
};

/** One long-lived `claude` process that accepts several user turns over stream-json stdin. */
class Chat {
  alive = true;
  private child: ChildProcessWithoutNullStreams;
  private pending?: Pending;
  private stderr = "";

  constructor() {
    mkdirSync(WORKDIR, { recursive: true });
    this.child = spawn(CLAUDE_BIN, FAST_ARGS, { cwd: WORKDIR, env: childEnv() });
    this.child.stderr.on("data", (c) => (this.stderr += c));
    createInterface({ input: this.child.stdout }).on("line", (line) => this.onLine(line));
    this.child.on("error", (e) => this.die(e));
    this.child.on("close", (code) => this.die(new Error(this.stderr.trim() || `claude exited with code ${code}`)));
  }

  send(prompt: string, onText?: (textSoFar: string) => void): Promise<ClaudeResult> {
    if (!this.alive) return Promise.reject(new Error("claude process is not running"));
    return new Promise((resolve, reject) => {
      this.pending = { resolve, reject, text: "", onText };
      this.child.stdin.write(JSON.stringify({ type: "user", message: { role: "user", content: prompt } }) + "\n");
    });
  }

  close() {
    this.child.stdin.end();
  }

  private die(e: Error) {
    this.alive = false;
    const p = this.pending;
    this.pending = undefined;
    p?.reject(e);
  }

  private onLine(line: string) {
    const p = this.pending;
    if (!p) return;
    let msg;
    try {
      msg = JSON.parse(line);
    } catch {
      return;
    }
    if (msg.type === "stream_event") {
      const ev = msg.event;
      if (ev.type === "message_start") p.text = "";
      else if (ev.type === "content_block_delta" && ev.delta?.type === "text_delta") {
        p.text += ev.delta.text;
        p.onText?.(p.text);
      }
    } else if (msg.type === "result") {
      this.pending = undefined;
      if (msg.is_error || typeof msg.result !== "string") p.reject(new Error(msg.result ?? "claude returned an error"));
      else p.resolve({ result: msg.result, raw: msg });
    }
  }
}

export type Answer = {
  result: string;
  mode: "fast" | "agentic";
  searched: boolean;
  timings: Record<string, number>;
  modelUsage: ClaudeResult["raw"]["modelUsage"];
  queries?: string[];
  /** Why the fast path gave up, when `mode` is "agentic" after trying it. */
  fallback?: string;
};

export type Hooks = {
  onText?: (textSoFar: string) => void;
  onStatus?: (status: string) => void;
};

const today = () => new Date().toISOString().slice(0, 10);

function plannerPrompt(question: string): string {
  return (
    `Today is ${today()}. Decide which web searches, if any, are needed to answer the user's question.\n` +
    `Reply with only a JSON array of 1 to 3 short keyword queries, written the way you would type them into a search engine ` +
    `(add the year for recent events). Reply [] when the conversation so far or stable general knowledge answers it: ` +
    `how-to and programming questions, definitions, explanations, concept comparisons, math, writing and chit-chat. ` +
    `Search for anything that can change or that you could be wrong about: current or recent events, prices, versions, ` +
    `releases, people in roles, sports, weather, or specific recent documents.\n\n` +
    `Question: ${question}`
  );
}

function answerPrompt(question: string, sources: string): string {
  const rules =
    "Be concise: under 80 words unless detail is requested. Use markdown and cite sources as markdown links. " +
    "Take versions, prices, dates, scores and roles from the sources, not from memory, preferring official sources and the most recent dates. " +
    "If the sources hold the answer or something close to it, give your best answer and mention any doubt. " +
    "Reply with exactly NEED_MORE and nothing else when the question asks for a specific fact, such as a winner, score or number, and the sources do not state it.";
  return sources
    ? `Answer the question using these web sources (retrieved ${today()}). Stable background knowledge is fine for context. ${rules}\n\nQuestion: ${question}\n\nSources:\n${sources}`
    : `Answer the question from the conversation and your own knowledge. ${rules}\n\nQuestion: ${question}`;
}

function parseQueries(reply: string, question: string): string[] {
  const array = /\[[\s\S]*\]/.exec(reply)?.[0];
  if (array) {
    try {
      const parsed: unknown = JSON.parse(array);
      if (Array.isArray(parsed)) return parsed.filter((q): q is string => typeof q === "string" && q.trim() !== "").slice(0, 3);
    } catch {
      // fall through to the raw question
    }
  }
  return [question];
}

const normalize = (url: string) => {
  try {
    const u = new URL(url);
    return u.hostname.replace(/^www\./, "") + u.pathname.replace(/\/$/, "");
  } catch {
    return url;
  }
};

// Round-robin across the result lists so every query contributes its best hits.
function mergeHits(lists: Hit[][], limit = 8): Hit[] {
  const seen = new Set<string>();
  const merged: Hit[] = [];
  for (let rank = 0; merged.length < limit && lists.some((l) => rank < l.length); rank++) {
    for (const list of lists) {
      const hit = list[rank];
      if (hit && !seen.has(normalize(hit.url)) && merged.length < limit) {
        seen.add(normalize(hit.url));
        merged.push(hit);
      }
    }
  }
  return merged;
}

// At most two pages per host: the second page of an authoritative site is often the one that holds the fact
// (nodejs.org's homepage says nothing about versions, nodejs.org/en/download does).
function pickToFetch(hits: Hit[], count = 5, perHost = 2): Hit[] {
  const perHostCount = new Map<string, number>();
  const picked: Hit[] = [];
  for (const h of hits) {
    let host: string;
    try {
      host = new URL(h.url).hostname;
    } catch {
      continue;
    }
    if (BLOCKED_HOSTS.test(host) || /\.pdf($|\?)/i.test(h.url) || (perHostCount.get(host) ?? 0) >= perHost) continue;
    perHostCount.set(host, (perHostCount.get(host) ?? 0) + 1);
    picked.push(h);
    if (picked.length === count) break;
  }
  return picked;
}

const termsOf = (queries: string[]) => [
  ...new Set(queries.join(" ").toLowerCase().split(/[^a-z0-9.]+/).filter((t) => t.length > 1 && !STOPWORDS.has(t))),
];

export class Asker {
  private chat?: Chat;
  private session = randomUUID();
  private agenticStarted = false;

  /** Spawns the claude process immediately so its startup overlaps with the user typing. */
  constructor(private readonly opts: { fast: boolean } = { fast: true }) {
    if (opts.fast) {
      this.chat = new Chat();
      // Open the TLS connection to the search engine now so the first search skips the handshake.
      fetch("https://www.bing.com/", { method: "HEAD", signal: AbortSignal.timeout(3000) }).catch(() => undefined);
    }
  }

  close() {
    this.chat?.close();
  }

  async ask(question: string, hooks: Hooks = {}): Promise<Answer> {
    let fallback: string | undefined;
    if (this.opts.fast) {
      try {
        return await this.fast(question, hooks);
      } catch (e) {
        fallback = (e as Error).message;
        hooks.onStatus?.("Searching deeper");
      }
    }
    return { ...(await this.agentic(question, hooks)), fallback };
  }

  private async agentic(question: string, hooks: Hooks): Promise<Answer> {
    const t0 = performance.now();
    const r = await askClaude(question, this.session, !this.agenticStarted, hooks.onText);
    this.agenticStarted = true;
    return {
      result: r.result,
      mode: "agentic",
      searched: true,
      timings: { total: performance.now() - t0 },
      modelUsage: r.raw.modelUsage,
    };
  }

  private async fast(question: string, hooks: Hooks): Promise<Answer> {
    if (!this.chat?.alive) this.chat = new Chat();
    const chat = this.chat;
    const timings: Record<string, number> = {};
    let mark = performance.now();
    const lap = (name: string) => {
      const now = performance.now();
      timings[name] = now - mark;
      mark = now;
    };

    hooks.onStatus?.("Planning");
    // The raw question is searched while the planner thinks. Keyword queries usually rank better, so these
    // results go last in the merge, but they cost no extra latency and keep recall up if the planner misfires.
    const rawSearch = bingSearch(question).catch(() => [] as Hit[]);
    const queries = parseQueries((await chat.send(plannerPrompt(question))).result, question);
    lap("plan");

    let sources = "";
    if (queries.length) {
      hooks.onStatus?.("Searching");
      const lists = await Promise.all(queries.map((q) => bingSearch(q).catch(() => [] as Hit[])));
      const hits = mergeHits([...lists, await rawSearch]);
      if (!hits.length) throw new Error("no search results");
      lap("search");

      hooks.onStatus?.("Reading");
      const fetched = pickToFetch(hits);
      const pages = new Map(
        await Promise.all(fetched.map(async (h) => [h.url, await fetchLines(h.url)] as const)),
      );
      lap("fetch");

      const terms = termsOf(queries);
      sources = hits
        .map((h, i) => {
          const lines = pages.get(h.url);
          const body = lines ? `\n${excerpt(lines, terms, 1800)}` : "";
          return `[${i + 1}] ${h.title} — ${h.url}\n${h.snippet}${body}`;
        })
        .join("\n\n");
    }

    if (process.env.ASK_DEBUG) console.error(`--- queries ${JSON.stringify(queries)}\n${answerPrompt(question, sources)}`);
    hooks.onStatus?.("Writing");
    // Hold back streamed text while it could still turn out to be the NEED_MORE sentinel.
    const onText = (t: string) => {
      if (!"NEED_MORE".startsWith(t.trimStart())) hooks.onText?.(t);
    };
    const answer = await chat.send(answerPrompt(question, sources), onText);
    lap("answer");
    if (process.env.ASK_DEBUG) console.error(`--- reply ${answer.result}`);

    if (/^\s*NEED_MORE/.test(answer.result)) throw new Error(`sources were not enough (queries: ${JSON.stringify(queries)})`);
    return {
      result: answer.result,
      mode: "fast",
      searched: queries.length > 0,
      timings,
      modelUsage: answer.raw.modelUsage,
      queries,
    };
  }
}
